-- Refreshed customer email templates (headline, preview text, receipt card, brand button).
-- Requires the dispatcher to provide {{amount_display}} and honour <!--preheader: ... --> (src/lib/email/queue.ts).
-- Previous copies are kept in email_templates_backup_20261111.
create table if not exists public.email_templates_backup_20261111 as table public.email_templates;
alter table public.email_templates_backup_20261111 enable row level security;

update public.email_templates set subject = $tpl$Payment received — {{tool}} access is active$tpl$, html_body = $tpl$<!--preheader: Your {{tool}} access is active. Receipt inside. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#15803d">&#10003; Payment received</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your {{tool}} access is active</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, thanks for your payment. You can start using {{tool}} right away from your dashboard.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Plan</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;text-transform:capitalize;">{{access_type}} access &middot; {{billing_period}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Amount paid</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{amount_display}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Payment date</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{start_date}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Access until</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{expiry_date}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Payment reference</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{reference}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{dashboard_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Open {{tool}} &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'payment_success';
update public.email_templates set subject = $tpl$Access confirmed — {{tool}}$tpl$, html_body = $tpl$<!--preheader: We've recorded your payment and switched on your {{tool}} access. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#15803d">&#10003; Access confirmed</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your {{tool}} access is ready</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, we've recorded your payment and switched on your access.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Plan</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;text-transform:capitalize;">{{access_type}} access &middot; {{billing_period}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Amount paid</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{amount_display}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Payment method</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;text-transform:capitalize;">{{payment_method}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Starts</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{start_date}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Access until</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{expiry_date}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Auto-renew</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;text-transform:capitalize;">{{auto_renew}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{dashboard_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Open {{tool}} &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'offline_confirmed';
update public.email_templates set subject = $tpl$We couldn't process your payment for {{tool}}$tpl$, html_body = $tpl$<!--preheader: Your payment for {{tool}} didn't go through. You can try again in a minute. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#b91c1c">Payment not completed</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your payment for {{tool}} didn't go through</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, we couldn't complete this payment, so your access hasn't been activated yet. You can try again. It only takes a minute.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Reason</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{reason}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Reference</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{reference}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{retry_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Try again &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">If you were debited but don't see your access, reply with the reference above and we'll sort it out quickly.</p>$tpl$, updated_at = now() where key = 'payment_failed';
update public.email_templates set subject = $tpl$Still interested in {{tool}}?$tpl$, html_body = $tpl$<!--preheader: Your {{tool}} selection is saved. Finish in one click. -->
<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">You're one step away from {{tool}}</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, you started checkout for <strong>{{tool}}</strong> but didn't finish. Your selection is saved.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Plan</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;text-transform:capitalize;">{{access_type}} access &middot; {{billing_period}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Price</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{amount_display}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{resume_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Complete checkout &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Had trouble paying? Reply to this email and we'll help.</p>$tpl$, updated_at = now() where key = 'abandoned_checkout';
update public.email_templates set subject = $tpl$Your Top Rated SEO Tools account is ready$tpl$, html_body = $tpl$<!--preheader: Your Top Rated SEO Tools account has been created. Set your password to sign in. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#1e4e8c">Welcome</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your account is ready</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, an account has been created for you at Top Rated SEO Tools. Set your password to sign in and see your tools.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{setup_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Set your password &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">For your security, we never send passwords by email.</p>$tpl$, updated_at = now() where key = 'customer_invite';
update public.email_templates set subject = $tpl$Payment received — Private Access setup in progress$tpl$, html_body = $tpl$<!--preheader: Payment received. Your private {{tool}} access is being prepared. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#b45309">Setup in progress</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">We're preparing your private {{tool}} access</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, your payment was successful. Your dedicated login is being set up and will appear in your dashboard.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Plan</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;text-transform:capitalize;">Private access &middot; {{billing_period}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;border-bottom:1px solid #e2e8f0;">Amount paid</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;border-bottom:1px solid #e2e8f0;">{{amount_display}}</td></tr><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Ready by</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{fulfil_by}}</td></tr></table><p style="margin:12px 0 16px;font-size:13px;line-height:1.6;color:#64748b">{{contact_admin_line}}</p>$tpl$, updated_at = now() where key = 'private_pending';
update public.email_templates set subject = $tpl$Your Private Access for {{tool}} is ready$tpl$, html_body = $tpl$<!--preheader: Your private {{tool}} access is ready in your dashboard. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#15803d">&#10003; Ready</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your private {{tool}} access is ready</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, your dedicated {{tool}} login is now available in your dashboard.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{dashboard_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Open {{tool}} &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'private_fulfilled';
update public.email_templates set subject = $tpl$Your {{tool}} subscription renewed$tpl$, html_body = $tpl$<!--preheader: Your {{tool}} subscription renewed. Access continues without interruption. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#15803d">&#10003; Renewed</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Your {{tool}} subscription renewed</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, your subscription renewed successfully. Your access continues without interruption.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Next billing date</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{next_billing_date}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{site_url}}/dashboard" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Open your dashboard &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'renewal_success';
update public.email_templates set subject = $tpl$Renewal failed for {{tool}}$tpl$, html_body = $tpl$<!--preheader: We couldn't renew your {{tool}} subscription. Update your payment to keep access. -->
<p style="margin:0 0 6px;font-size:12px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#b91c1c">Action needed</p><h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">We couldn't renew {{tool}}</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, your renewal payment didn't go through. Update your payment details to keep your access.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{billing_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Update payment &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'renewal_failed';
update public.email_templates set subject = $tpl$Auto-renewal turned off for {{tool}}$tpl$, html_body = $tpl$<!--preheader: Auto-renewal is off. Your {{tool}} access continues until {{expiry_date}}. -->
<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">Auto-renewal is off for {{tool}}</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, you won't be charged again for {{tool}}. You can keep using it until your current period ends.</p><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="border:1px solid #e2e8f0;border-radius:10px;border-collapse:separate;background:#f8fafc;margin:4px 0 6px"><tr><td style="padding:11px 14px;font-size:13px;color:#64748b;">Access until</td><td style="padding:11px 14px;font-size:14px;font-weight:600;color:#0f172a;text-align:right;">{{expiry_date}}</td></tr></table><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{site_url}}/dashboard" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Manage your tools &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">Questions? Just reply to this email and our team will help.</p>$tpl$, updated_at = now() where key = 'renewal_disabled';
update public.email_templates set subject = $tpl$How is {{tool}} working for you?$tpl$, html_body = $tpl$<!--preheader: Got a minute? Tell other customers how {{tool}} is working for you. -->
<h1 style="margin:0 0 12px;font-size:22px;line-height:1.3;font-weight:700;color:#0f172a">How is {{tool}} working for you?</h1><p style="margin:0px 0 16px;font-size:15px;line-height:1.6;color:#334155">Hi {{name}}, thanks for choosing {{tool}}. A short review helps other customers decide, and helps us keep improving.</p><table role="presentation" cellpadding="0" cellspacing="0" style="margin:22px 0 8px"><tr><td style="background:{{brand_color}};border-radius:8px"><a href="{{review_url}}" style="display:inline-block;padding:12px 22px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;border-radius:8px">Write a quick review &rarr;</a></td></tr></table><p style="margin:8px 0 16px;font-size:13px;line-height:1.6;color:#64748b">It takes less than a minute.</p>$tpl$, updated_at = now() where key = 'review_request';
